-- Layercake.vw_silv_contact_local_group (src/sql/Layercake/Views/Layercake.vw_silv_contact_local_group.sql)
/*====================================================================
    Layercake.vw_silv_contact_local_group
    The one place that decides each member's local group, country and
    regions (ADR-016 Option A, AMD-009). One row per live brnz_contact row.
    contact_country_id is the own country exactly as Phase 1 derives
    silv_member_base.country_id: silv_ref_country matched on rics_countryid,
    0 where rics_countryid is null or not found (Q-069 c).
    A member whose rics_localgroupid names a reportable silv_ref_local_group
    row takes that group's id, country and both regions; every other member
    takes local_group_id 0 and the own country with its own regions in every
    field. Fields are never mixed, and -2 is never given.
====================================================================*/
CREATE OR ALTER VIEW Layercake.vw_silv_contact_local_group
AS
SELECT c.ContactId AS contact_id,
       c.Rics_contactno AS contact_no,
       oc.contact_country_id,
       ISNULL(lg.id, 0) AS local_group_id,
       CASE WHEN lg.id IS NULL THEN oc.contact_country_id ELSE lg.country_id END AS country_id,
       CASE WHEN lg.id IS NULL THEN own.region_name ELSE lg.region_name END AS region_name,
       CASE WHEN lg.id IS NULL THEN own.market_reporting_region ELSE lg.market_reporting_region END AS market_reporting_region,
       own.region_name AS contact_region_name,
       own.market_reporting_region AS contact_market_reporting_region
FROM Layercake.brnz_contact AS c
LEFT JOIN Layercake.silv_ref_country AS ctry
    ON ctry.country_id = c.rics_countryid
CROSS APPLY (SELECT ISNULL(ctry.id, 0) AS contact_country_id) AS oc
LEFT JOIN Layercake.silv_ref_country AS own
    ON own.id = oc.contact_country_id
LEFT JOIN Layercake.silv_ref_local_group AS lg
    ON  lg.local_group_bk = c.rics_localgroupid
    AND lg.is_reportable = 1
WHERE c._is_deleted = 0;
GO
-- Layercake.usp_load_brnz_local_group_detail (src/sql/Layercake/Procedures/Layercake.usp_load_brnz_local_group_detail.sql)
/*====================================================================
    Layercake.usp_load_brnz_local_group_detail
    Bronze layer - CE.vwLocalGroup -> Layercake.brnz_local_group_detail
    1:1 landing at local group grain, keyed on apuk_localgroupid (RULE-169,
    ADR-014): insert new, update changed (and restore reappearing),
    soft-delete gone; row-count check (RULE-005); logged. Values are not
    transformed. The country-grain brnz_local_group is not touched.
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_brnz_local_group_detail
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id    bigint,
            @ins       int,
            @upd       int,
            @del       int,
            @src_count bigint,
            @tgt_count bigint,
            @err       nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'bronze', 'brnz_local_group_detail', @log_id OUTPUT;

        -- Staged in the target's types with the key NOT NULL and unique: a NULL
        -- key fails the load with 515 and a duplicate key with 2627, before
        -- bronze is touched; no row is skipped (DES-001, as brnz_concession).
        CREATE TABLE #src_local_group
        (
            apuk_localgroupid       uniqueidentifier NOT NULL PRIMARY KEY CLUSTERED,
            apuk_name               nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            apuk_code               nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            apuk_countryid          uniqueidentifier NULL,
            apuk_worldregionid_name nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            market_reporting_region varchar(15)   COLLATE DATABASE_DEFAULT NULL,
            statecode               int           NULL
        );

        INSERT INTO #src_local_group
            (apuk_localgroupid, apuk_name, apuk_code, apuk_countryid, apuk_worldregionid_name,
             market_reporting_region, statecode)
        SELECT lg.apuk_localgroupid, lg.apuk_name, lg.apuk_code, lg.apuk_countryid,
               lg.apuk_worldregionid_name, lg.Market_reporting_region, lg.statecode
        FROM CE.vwLocalGroup AS lg;

        BEGIN TRANSACTION;

        -- Strings compare as bytes so a case-only or trailing-space change in the
        -- source is landed (bronze is byte for byte); EXCEPT treats NULLs as equal.
        UPDATE tgt
        SET apuk_name               = s.apuk_name,
            apuk_code               = s.apuk_code,
            apuk_countryid          = s.apuk_countryid,
            apuk_worldregionid_name = s.apuk_worldregionid_name,
            market_reporting_region = s.market_reporting_region,
            statecode               = s.statecode,
            _is_deleted             = 0,
            _deleted_at             = NULL,
            _updated_at             = SYSDATETIME()
        FROM Layercake.brnz_local_group_detail AS tgt
        INNER JOIN #src_local_group AS s
            ON s.apuk_localgroupid = tgt.apuk_localgroupid
        WHERE tgt._is_deleted = 1
           OR EXISTS (SELECT CAST(s.apuk_name AS varbinary(200)), CAST(s.apuk_code AS varbinary(200)),
                             s.apuk_countryid, CAST(s.apuk_worldregionid_name AS varbinary(200)),
                             CAST(s.market_reporting_region AS varbinary(15)), s.statecode
                      EXCEPT
                      SELECT CAST(tgt.apuk_name AS varbinary(200)), CAST(tgt.apuk_code AS varbinary(200)),
                             tgt.apuk_countryid, CAST(tgt.apuk_worldregionid_name AS varbinary(200)),
                             CAST(tgt.market_reporting_region AS varbinary(15)), tgt.statecode);
        SET @upd = @@ROWCOUNT;

        INSERT INTO Layercake.brnz_local_group_detail
            (apuk_localgroupid, apuk_name, apuk_code, apuk_countryid, apuk_worldregionid_name,
             market_reporting_region, statecode)
        SELECT s.apuk_localgroupid, s.apuk_name, s.apuk_code, s.apuk_countryid, s.apuk_worldregionid_name,
               s.market_reporting_region, s.statecode
        FROM #src_local_group AS s
        WHERE NOT EXISTS (SELECT 1
                          FROM Layercake.brnz_local_group_detail AS t
                          WHERE t.apuk_localgroupid = s.apuk_localgroupid);
        SET @ins = @@ROWCOUNT;

        UPDATE tgt
        SET _is_deleted = 1,
            _deleted_at = SYSDATETIME(),
            _updated_at = SYSDATETIME()
        FROM Layercake.brnz_local_group_detail AS tgt
        WHERE tgt._is_deleted = 0
          AND NOT EXISTS (SELECT 1
                          FROM #src_local_group AS s
                          WHERE s.apuk_localgroupid = tgt.apuk_localgroupid);
        SET @del = @@ROWCOUNT;

        SELECT @src_count = COUNT_BIG(*) FROM #src_local_group;
        SELECT @tgt_count = COUNT_BIG(*) FROM Layercake.brnz_local_group_detail WHERE _is_deleted = 0;
        IF @src_count <> @tgt_count
            RAISERROR('Row count mismatch after sync of Layercake.brnz_local_group_detail: source %I64d vs active target %I64d.', 16, 1, @src_count, @tgt_count);

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        THROW;
    END CATCH;
END;
GO
-- Layercake.usp_load_brnz_contact (src/sql/Layercake/Procedures/Layercake.usp_load_brnz_contact.sql) (changed)
/*====================================================================
    Layercake.usp_load_brnz_contact
    Bronze layer - loads one table
====================================================================*/

/*************************************************************************************
    11 - BRONZE MODULES: one stored procedure per bronze table
    ---------------------------------------------------------------------------------
    Splits the monolithic Layercake.usp_load_bronze (01_usp_load_bronze.sql) into
    nine independent modules, one per target table. The orchestrator that calls
    them in order lives in 14_orchestrators.sql and keeps the name
    Layercake.usp_load_bronze, so nothing upstream changes.

    Each module is self-contained:
      * takes @run_id (generated if run standalone, so any module can be run on
        its own for a targeted reload);
      * opens its own etl_run_log step under the SAME step name the monolith
        used, so existing monitoring queries are unaffected;
      * runs its own transaction - a failure rolls back only that table;
      * logs the failure against its own step and re-throws, so the caller
        (orchestrator or SQL Agent / ADF) sees the error.

    The per-table sync pattern is UNCHANGED from 01 (see that file's header for
    the reasoning) - only the procedure boundaries are new:

      1. Snapshot the source into a keyed #temp.
      2. UPDATE changed payloads + resurrect soft-deleted rows that reappeared.
      3. INSERT rows not yet in bronze (backfills, not just yesterday).
      4. Soft-DELETE rows no longer in the source (_is_deleted = 1).
      5. Reconciliation check: active bronze rows must equal the snapshot.

    NO business filters here: test-record exclusion, statecode, approved = 1 and
    the Student apuk_membergrade exclusion all live in silver.

    The #temp tables are dropped automatically when each procedure returns, so
    the explicit cleanup the monolith needed between steps is gone.

    Modules, in dependency order (they are mutually independent - the order is
    only for readability and matches the monolith):
        1. usp_load_brnz_contact
        2. usp_load_brnz_enrolment
        3. usp_load_brnz_rics_record
        4. usp_load_brnz_local_group
        5. usp_load_brnz_cust_trans
        6. usp_load_brnz_subs_status
        7. usp_load_brnz_option_set
        8. usp_load_brnz_route
        9. usp_load_brnz_contact_test_record

    DEPLOY NOTE: remove 01_usp_load_bronze.sql from the deploy folder so
    run-scripts.ps1 does not also create the monolithic version. 14 recreates
    Layercake.usp_load_bronze as the orchestrator.
*************************************************************************************/

/*====================================================================
    1. CE.vwContact -> Layercake.brnz_contact
====================================================================*/
create or alter procedure Layercake.usp_load_brnz_contact
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id    bigint,
            @ins       int,
            @upd       int,
            @del       int,
            @src_count bigint,
            @tgt_count bigint,
            @err       nvarchar(4000);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'bronze', 'brnz_contact', @log_id output;
        begin tran;

        -- CreatedOn / StateCode added 20260928_01 for the enrolment-exception
        -- capture in silver (usp_load_ref_enrolment_exception) - see that
        -- module and the column comments in 02_Tables/Bronze.
        -- rics_localgroupid added by MOD-030 (RULE-169). It takes part in the
        -- change test, so the first run after deployment fills it on every
        -- live row once and a rerun then updates nothing.
        select ContactId, Rics_contactno, Rics_ElectionDate, Rics_LapsedDate,
               MemberGrade_Description, GenderCode, rics_countryid,
               CreatedOn, StateCode, rics_localgroupid
        into #src_contact
        from CE.vwContact;
        create unique clustered index cx_src_contact on #src_contact (ContactId);

        -- changed payloads + reappeared rows
        update tgt
        set Rics_contactno          = s.Rics_contactno,
            Rics_ElectionDate       = s.Rics_ElectionDate,
            Rics_LapsedDate         = s.Rics_LapsedDate,
            MemberGrade_Description = s.MemberGrade_Description,
            GenderCode              = s.GenderCode,
            rics_countryid          = s.rics_countryid,
            CreatedOn               = s.CreatedOn,
            StateCode               = s.StateCode,
            rics_localgroupid       = s.rics_localgroupid,
            _is_deleted             = 0,
            _deleted_at             = null,
            _updated_at             = sysdatetime()
        from Layercake.brnz_contact tgt
        join #src_contact s on s.ContactId = tgt.ContactId
        where tgt._is_deleted = 1
           or exists (select s.Rics_contactno, s.Rics_ElectionDate, s.Rics_LapsedDate,
                             s.MemberGrade_Description, s.GenderCode, s.rics_countryid,
                             s.CreatedOn, s.StateCode, s.rics_localgroupid
                      except
                      select tgt.Rics_contactno, tgt.Rics_ElectionDate, tgt.Rics_LapsedDate,
                             tgt.MemberGrade_Description, tgt.GenderCode, tgt.rics_countryid,
                             tgt.CreatedOn, tgt.StateCode, tgt.rics_localgroupid);
        set @upd = @@rowcount;

        -- new rows (also backfills anything missing, not just the last day)
        insert into Layercake.brnz_contact
        (ContactId, Rics_contactno, Rics_ElectionDate, Rics_LapsedDate,
         MemberGrade_Description, GenderCode, rics_countryid, CreatedOn, StateCode,
         rics_localgroupid)
        select s.ContactId, s.Rics_contactno, s.Rics_ElectionDate, s.Rics_LapsedDate,
               s.MemberGrade_Description, s.GenderCode, s.rics_countryid,
               s.CreatedOn, s.StateCode, s.rics_localgroupid
        from #src_contact s
        where not exists (select 1 from Layercake.brnz_contact t where t.ContactId = s.ContactId);
        set @ins = @@rowcount;

        -- rows gone from source -> soft delete
        update tgt
        set _is_deleted = 1, _deleted_at = sysdatetime(), _updated_at = sysdatetime()
        from Layercake.brnz_contact tgt
        where tgt._is_deleted = 0
          and not exists (select 1 from #src_contact s where s.ContactId = tgt.ContactId);
        set @del = @@rowcount;

        -- active rows must mirror the source snapshot exactly
        select @src_count = count(*) from #src_contact;
        select @tgt_count = count(*) from Layercake.brnz_contact where _is_deleted = 0;
        if @src_count <> @tgt_count
            raiserror('Row count mismatch after sync of Layercake.brnz_contact: source %I64d vs active target %I64d.', 16, 1, @src_count, @tgt_count);

        commit;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, @del;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, @del, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_bronze (src/sql/Layercake/Procedures/Layercake.usp_load_bronze.sql) (changed)
/*====================================================================
    Layercake.usp_load_bronze
    Orchestration - calls the per-table modules in order
====================================================================*/

/*************************************************************************************
    14 - ORCHESTRATORS
    ---------------------------------------------------------------------------------
    Recreates the four entry points that used to BE the pipeline, as thin
    orchestrators over the per-table modules in 11 / 12 / 13:

        Layercake.usp_load_bronze       -> the 9 bronze modules
        Layercake.usp_load_silver       -> the 14 silver modules
        Layercake.usp_load_gold         -> the 12 gold modules
        Layercake.usp_run_daily_load    -> bronze -> silver -> gold, one run_id

    ENTRY POINTS AND SIGNATURES ARE UNCHANGED. An existing SQL Agent job, ADF
    pipeline or ad hoc call keeps working exactly as before:

        exec Layercake.usp_run_daily_load;
        exec Layercake.usp_run_daily_load @FullRebuild = 1;

    ---------------------------------------------------------------------------------
    WHY THE ORCHESTRATORS HAVE NO TRY/CATCH
    ---------------------------------------------------------------------------------
    Each module already opens its own etl_run_log step, rolls back its own
    transaction on failure, logs the error against that step, and re-throws. An
    orchestrator adding another catch would log nothing new and would only
    obscure the error line. So the layer orchestrators are a plain ordered
    sequence: the first module to throw stops the layer, and the exception
    propagates to usp_run_daily_load, which logs the 'run' row as Failed and
    re-throws to the scheduler. This is the same log shape and the same failure
    behaviour as the monolithic procs.

    ---------------------------------------------------------------------------------
    ORDER IS THE CONTRACT
    ---------------------------------------------------------------------------------
    The modules are independent procedures but NOT independent of each other's
    output. The sequences below are the dependency order; the notable edges are:

      * every silver reference module must precede usp_load_silv_member_base
        (the base resolves country / gender / rpq / lapse-reason ids);
      * usp_load_ref_campaign_year_config must follow usp_load_ref_date_spine
        (it derives its campaign years from the spine);
      * usp_load_silv_member_base must precede membership_events, data_anomaly,
        member_profile and annual_rate_base (all four read it);
      * usp_load_silv_member_state_ranges must follow membership_events (the
        ranges derive entirely from the events) and precede member_profile
        (the affected-date calculation reads the ranges);
      * usp_load_silv_daily_count must follow state_ranges, member_profile and
        payment_events;
      * every gold dimension must precede the facts that key on it, and
        usp_load_dim_date must precede both date-keyed facts.

    ---------------------------------------------------------------------------------
    RUNNING A SINGLE MODULE
    ---------------------------------------------------------------------------------
    Every module takes an optional @run_id and generates one if omitted, so any
    single table can be rebuilt on its own and still be traceable in
    etl_run_log:

        -- reload one bronze table after a source fix
        exec Layercake.usp_load_brnz_subs_status;

        -- re-derive the events (and everything that hangs off them)
        exec Layercake.usp_load_silv_member_base;
        exec Layercake.usp_load_silv_membership_events;
        exec Layercake.usp_load_silv_member_state_ranges;

        -- tie several targeted modules into ONE traceable run
        declare @rid uniqueidentifier = newid();
        exec Layercake.usp_load_silv_member_base        @run_id = @rid;
        exec Layercake.usp_load_silv_membership_events  @run_id = @rid;

    APPLYING A RETROSPECTIVE CORRECTION (unchanged workflow):

        -- what history has drifted from source?
        select * from Layercake.etl_daily_count_pending_rebuild where applied_at is null;
        -- apply it (outside the daily window - this can be a long walk):
        exec Layercake.usp_load_silver @RebuildFrom = '2025-10-01';
        -- ...or just the daily count, if nothing upstream needs re-deriving:
        exec Layercake.usp_load_silv_daily_count @RebuildFrom = '2025-10-01';

    ---------------------------------------------------------------------------------
    MONITORING (unchanged)
    ---------------------------------------------------------------------------------
        -- latest run, step by step
        select top 50 * from Layercake.etl_run_log
        where run_id = (select top 1 run_id from Layercake.etl_run_log
                        where layer = 'run' order by started_at desc)
        order by log_id;

        -- failures in the last 7 days
        select * from Layercake.etl_run_log
        where status = 'Failed' and started_at >= dateadd(day, -7, sysdatetime())
        order by started_at desc;

        -- live sub-step progress during a long run
        exec Layercake.usp_etl_watch;

    DEPLOY NOTE: deploy 11, 12 and 13 before this file. Remove
    01_usp_load_bronze.sql, 02_usp_load_silver_v9.sql, 03_usp_load_gold_v3_2.sql
    and 04_usp_run_daily_load.sql (and any earlier versions) from the deploy
    folder - this file owns all four names now.
*************************************************************************************/

/*====================================================================
    BRONZE
    ------------------------------------------------------------------
    The bronze tables are mutually independent (each syncs one source
    object into one landing table), so this order is the monolith's
    order and nothing more. Any of them can be run alone. MOD-030 adds
    the local group landing at local group grain (ADR-014) beside the
    country-grain local group load.
====================================================================*/
create or alter procedure Layercake.usp_load_bronze
    @run_id uniqueidentifier = null    -- supplied by the orchestrator; generated if run standalone
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    exec Layercake.usp_load_brnz_contact             @run_id = @run_id;
    exec Layercake.usp_load_brnz_enrolment           @run_id = @run_id;
    exec Layercake.usp_load_brnz_rics_record         @run_id = @run_id;
    exec Layercake.usp_load_brnz_local_group         @run_id = @run_id;
    exec Layercake.usp_load_brnz_local_group_detail  @run_id = @run_id;
    exec Layercake.usp_load_brnz_cust_trans          @run_id = @run_id;
    exec Layercake.usp_load_brnz_subs_status         @run_id = @run_id;
    exec Layercake.usp_load_brnz_option_set          @run_id = @run_id;
    exec Layercake.usp_load_brnz_route               @run_id = @run_id;
    exec Layercake.usp_load_brnz_contact_test_record @run_id = @run_id;
end
GO
-- Layercake.usp_load_silv_ref_local_group (src/sql/Layercake/Procedures/Layercake.usp_load_silv_ref_local_group.sql)
/*====================================================================
    Layercake.usp_load_silv_ref_local_group
    Silver layer - brnz_local_group_detail + silv_ref_country
                   -> Layercake.silv_ref_local_group, silv_ref_country_region
    Insert-and-update by local_group_bk, as silv_ref_country is: new groups
    added, changed values updated, ids never change, unchanged rows
    untouched. The reserved rows 0 Unknown and -2 Not applicable have no
    business key, so the load never matches or changes them.
    is_reportable is the usable test of RULE-171 (ADR-016 Option A, AMD-009):
    live in bronze, statecode 0, a country found in silv_ref_country and both
    region values neither null nor blank. A group gone from bronze keeps its
    row with is_reportable 0.
    dim_country_id (ADR-015): the country's own id where both of the group's
    regions equal the country's own, else the silv_ref_country_region id of
    the combination, which is added first if missing (insert-only).
    Regions are matched as the database collation compares them, so a group
    region differing from its country's only in case or trailing spaces uses
    the country's own row. silv_ref_country is only read.
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_silv_ref_local_group
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id     bigint,
            @ins        int,
            @upd        int,
            @ins_region int,
            @now        datetime2(3),
            @substep_ts datetime2(3) = SYSDATETIME(),
            @err        nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'silver', 'silv_ref_local_group', @log_id OUTPUT;

        SET @now = SYSDATETIME();

        -- Every bronze group, live or soft-deleted, with blank regions held as NULL.
        CREATE TABLE #grp
        (
            local_group_bk          uniqueidentifier NOT NULL PRIMARY KEY CLUSTERED,
            local_group_name        nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            local_group_code        nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            country_id              int           NULL,
            region_name             nvarchar(100) COLLATE DATABASE_DEFAULT NULL,
            market_reporting_region varchar(15)   COLLATE DATABASE_DEFAULT NULL,
            statecode               int           NULL,
            is_reportable           bit           NOT NULL,
            own_region_name         nvarchar(200) COLLATE DATABASE_DEFAULT NULL,
            own_market_region       varchar(15)   COLLATE DATABASE_DEFAULT NULL,
            dim_country_id          int           NULL
        );

        INSERT INTO #grp
            (local_group_bk, local_group_name, local_group_code, country_id, region_name,
             market_reporting_region, statecode, is_reportable, own_region_name, own_market_region)
        SELECT b.apuk_localgroupid,
               b.apuk_name,
               b.apuk_code,
               c.id,
               r.region_name,
               r.market_reporting_region,
               b.statecode,
               CASE WHEN b._is_deleted = 0
                     AND b.statecode = 0
                     AND c.id IS NOT NULL
                     AND r.region_name IS NOT NULL
                     AND r.market_reporting_region IS NOT NULL
                    THEN 1 ELSE 0 END,
               c.region_name,
               c.market_reporting_region
        FROM Layercake.brnz_local_group_detail AS b
        LEFT JOIN Layercake.silv_ref_country AS c
            ON c.country_id = b.apuk_countryid
        CROSS APPLY (SELECT CASE WHEN LTRIM(RTRIM(b.apuk_worldregionid_name)) = N'' THEN NULL
                                 ELSE b.apuk_worldregionid_name END AS region_name,
                            CASE WHEN LTRIM(RTRIM(b.market_reporting_region)) = '' THEN NULL
                                 ELSE b.market_reporting_region END AS market_reporting_region) AS r;

        BEGIN TRANSACTION;

        -- Combinations a reportable group needs that its country's own row does not give.
        INSERT INTO Layercake.silv_ref_country_region (country_ref_id, region_name, market_reporting_region, load_id, created_at)
        SELECT DISTINCT g.country_id, g.region_name, g.market_reporting_region, @log_id, @now
        FROM #grp AS g
        WHERE g.is_reportable = 1
          AND NOT (g.region_name = g.own_region_name AND g.market_reporting_region = g.own_market_region)
          AND NOT EXISTS (SELECT 1
                          FROM Layercake.silv_ref_country_region AS x
                          WHERE x.country_ref_id = g.country_id
                            AND x.region_name = g.region_name
                            AND x.market_reporting_region = g.market_reporting_region);
        SET @ins_region = @@ROWCOUNT;

        UPDATE g
        SET dim_country_id = CASE WHEN g.region_name = g.own_region_name
                                   AND g.market_reporting_region = g.own_market_region
                                  THEN g.country_id
                                  ELSE x.id END
        FROM #grp AS g
        LEFT JOIN Layercake.silv_ref_country_region AS x
            ON  x.country_ref_id = g.country_id
            AND x.region_name = g.region_name
            AND x.market_reporting_region = g.market_reporting_region
        WHERE g.is_reportable = 1;

        -- Strings compare as bytes: the collation is case-insensitive and '='
        -- ignores trailing spaces, and such a change must still reach the list.
        UPDATE t
        SET local_group_name        = g.local_group_name,
            local_group_code        = g.local_group_code,
            country_id              = g.country_id,
            region_name             = g.region_name,
            market_reporting_region = g.market_reporting_region,
            statecode               = g.statecode,
            is_reportable           = g.is_reportable,
            dim_country_id          = g.dim_country_id,
            load_id                 = @log_id,
            updated_at              = @now
        FROM Layercake.silv_ref_local_group AS t
        INNER JOIN #grp AS g
            ON g.local_group_bk = t.local_group_bk
        WHERE EXISTS (SELECT CAST(g.local_group_name AS varbinary(200)), CAST(g.local_group_code AS varbinary(200)),
                             g.country_id, CAST(g.region_name AS varbinary(200)),
                             CAST(g.market_reporting_region AS varbinary(15)), g.statecode,
                             g.is_reportable, g.dim_country_id
                      EXCEPT
                      SELECT CAST(t.local_group_name AS varbinary(200)), CAST(t.local_group_code AS varbinary(200)),
                             t.country_id, CAST(t.region_name AS varbinary(200)),
                             CAST(t.market_reporting_region AS varbinary(15)), t.statecode,
                             t.is_reportable, t.dim_country_id);
        SET @upd = @@ROWCOUNT;

        -- A group no longer in bronze at all keeps its row and id but gives no member a region.
        UPDATE t
        SET is_reportable  = 0,
            dim_country_id = NULL,
            load_id        = @log_id,
            updated_at     = @now
        FROM Layercake.silv_ref_local_group AS t
        WHERE t.local_group_bk IS NOT NULL
          AND (t.is_reportable = 1 OR t.dim_country_id IS NOT NULL)
          AND NOT EXISTS (SELECT 1 FROM #grp AS g WHERE g.local_group_bk = t.local_group_bk);
        SET @upd = @upd + @@ROWCOUNT;

        INSERT INTO Layercake.silv_ref_local_group
            (local_group_bk, local_group_name, local_group_code, country_id, region_name,
             market_reporting_region, statecode, is_reportable, dim_country_id, load_id, created_at, updated_at)
        SELECT g.local_group_bk, g.local_group_name, g.local_group_code, g.country_id, g.region_name,
               g.market_reporting_region, g.statecode, g.is_reportable, g.dim_country_id, @log_id, @now, @now
        FROM #grp AS g
        WHERE NOT EXISTS (SELECT 1 FROM Layercake.silv_ref_local_group AS t WHERE t.local_group_bk = g.local_group_bk);
        SET @ins = @@ROWCOUNT;

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_progress @log_id, N'silv_ref_country_region combinations added', @ins_region, @substep_ts OUTPUT;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, 0, @err;
        THROW;
    END CATCH;
END;
GO
-- Layercake.usp_load_dim_local_group (src/sql/Layercake/Procedures/Layercake.usp_load_dim_local_group.sql)
/*====================================================================
    Layercake.usp_load_dim_local_group
    Gold layer - Layercake.silv_ref_local_group -> Layercake.dim_local_group
    Mirrors the list by id, both reserved rows included, as the other gold
    dimensions do: inserts missing ids, updates changed names, leaves
    unchanged rows untouched. Logged. Never deletes: list ids never leave
    silver, and facts may point at any of them.
====================================================================*/
CREATE OR ALTER PROCEDURE Layercake.usp_load_dim_local_group
    @run_id uniqueidentifier = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @run_id IS NULL SET @run_id = NEWID();

    DECLARE @log_id bigint,
            @ins    int,
            @upd    int,
            @now    datetime2(3),
            @err    nvarchar(4000);

    BEGIN TRY
        EXEC Layercake.usp_etl_log_start @run_id, 'gold', 'dim_local_group', @log_id OUTPUT;

        SET @now = SYSDATETIME();

        BEGIN TRANSACTION;

        -- Names compare as bytes: the collation is case-insensitive and '='
        -- ignores trailing spaces, and such a change must still reach the dimension.
        UPDATE d
        SET local_group_name = s.local_group_name,
            load_id          = @log_id,
            updated_at       = @now
        FROM Layercake.dim_local_group AS d
        INNER JOIN Layercake.silv_ref_local_group AS s
            ON s.id = d.id
        WHERE EXISTS (SELECT CAST(s.local_group_name AS varbinary(200))
                      EXCEPT
                      SELECT CAST(d.local_group_name AS varbinary(200)));
        SET @upd = @@ROWCOUNT;

        INSERT INTO Layercake.dim_local_group (id, local_group_name, load_id, created_at, updated_at)
        SELECT s.id, s.local_group_name, @log_id, @now, @now
        FROM Layercake.silv_ref_local_group AS s
        WHERE NOT EXISTS (SELECT 1 FROM Layercake.dim_local_group AS d WHERE d.id = s.id);
        SET @ins = @@ROWCOUNT;

        COMMIT TRANSACTION;
        EXEC Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        SET @err = CONCAT(ERROR_MESSAGE(), ' (error ', ERROR_NUMBER(), ', line ', ERROR_LINE(), ')');
        IF @log_id IS NOT NULL
            EXEC Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, 0, @err;
        THROW;
    END CATCH;
END;
GO
-- Layercake.usp_load_dim_country (src/sql/Layercake/Procedures/Layercake.usp_load_dim_country.sql) (changed)
/*====================================================================
    Layercake.usp_load_dim_country
    Gold layer - loads one table
====================================================================*/

/*====================================================================
    4. Layercake.dim_country
    ------------------------------------------------------------------
    Carries both region flavours; region reporting rolls up from here.
    MOD-030 (ADR-015): also mirrors every silv_ref_country_region
    combination under its own id (from 1000001), with its country's GUID
    and name and the combination's two regions, so a fact's country_id can
    reach a local group's region. The silv_ref_country rows are written
    exactly as before. Nothing is deleted.
====================================================================*/
create or alter procedure Layercake.usp_load_dim_country
    @run_id uniqueidentifier = null
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    declare @log_id bigint, @ins int, @upd int, @err nvarchar(4000);

    begin try
        exec Layercake.usp_etl_log_start @run_id, 'gold', 'dim_country', @log_id output;

        select s.id, s.country_id, s.country_name, s.region_name, s.market_reporting_region
        into #src_country
        from Layercake.silv_ref_country s
        union all
        select r.id, c.country_id, c.country_name, r.region_name, r.market_reporting_region
        from Layercake.silv_ref_country_region r
        join Layercake.silv_ref_country c on c.id = r.country_ref_id;

        begin tran;

        update d
        set country_id              = s.country_id,
            country_name            = s.country_name,
            region_name             = s.region_name,
            market_reporting_region = s.market_reporting_region
        from Layercake.dim_country d
        join #src_country s on s.id = d.id
        where exists (select s.country_id, s.country_name, s.region_name, s.market_reporting_region
                      except
                      select d.country_id, d.country_name, d.region_name, d.market_reporting_region);
        set @upd = @@rowcount;

        insert into Layercake.dim_country (id, country_id, country_name, region_name, market_reporting_region)
        select s.id, s.country_id, s.country_name, s.region_name, s.market_reporting_region
        from #src_country s
        where not exists (select 1 from Layercake.dim_country d where d.id = s.id);
        set @ins = @@rowcount;

        commit;
        exec Layercake.usp_etl_log_end @log_id, 'Success', @ins, @upd, 0;
    end try
    begin catch
        if xact_state() <> 0 rollback;
        set @err = concat(error_message(), ' (error ', error_number(), ', line ', error_line(), ')');
        if @log_id is not null
            exec Layercake.usp_etl_log_end @log_id, 'Failed', @ins, @upd, 0, @err;
        throw;
    end catch
end
GO
-- Layercake.usp_load_silver (src/sql/Layercake/Procedures/Layercake.usp_load_silver.sql) (changed)
/*====================================================================
    Layercake.usp_load_silver
    Orchestration - calls the per-table modules in order
====================================================================*/

/*====================================================================
    SILVER
    ------------------------------------------------------------------
    Build order: refs -> date spine -> campaign year config -> payment
    events -> enrolment exceptions -> member base -> membership events
    -> anomalies -> state ranges -> member profile -> daily counts ->
    annual rate base.

    Parameters (all but @SkipDailyCount passed straight through to the
    daily-count module, the only one that takes them):
      @run_id              - orchestrator run id (generated if standalone)
      @FullRebuild         - 1 clears the loaded markers for the WHOLE
                             spine (from 2020-10-01) so both daily count
                             tables are rebuilt from scratch by this
                             run's chunked walk. Refs / events / ranges /
                             rate base always self-correct regardless.
      @RebuildFrom         - clear the loaded markers from this date
                             forward and re-do those dates. The
                             deliberate way to apply a retrospective
                             correction flagged in
                             etl_daily_count_pending_rebuild. Ignored
                             when @FullRebuild = 1.
      @DailyCountBatchDays - chunk size for the daily-count walk, and
                             therefore the granularity at which a failed
                             run resumes (default 31; minimum 1).
      @SkipDailyCount      - 1 leaves out the daily count (ADR-012):
                             usp_run_daily_load runs it itself after the
                             payment segment loads, so it uses the
                             member-year attributes of the same run.
                             Leave at 0 when calling by hand.
====================================================================*/
create or alter procedure Layercake.usp_load_silver
    @run_id              uniqueidentifier = null,
    @FullRebuild         bit  = 0,
    @RebuildFrom         date = null,
    @DailyCountBatchDays int  = 31,
    @SkipDailyCount      bit  = 0
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    -- reference tables: insert-new + update-in-place only, so surrogate ids
    -- stay stable and the incremental gold facts keep resolving
    exec Layercake.usp_load_silv_ref_assessment_route @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_rpq_variant      @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_country          @run_id = @run_id;
    exec Layercake.usp_load_silv_ref_lapse_reason     @run_id = @run_id;

    -- MOD-030 (REQ-027): the local group list resolves each group's country
    -- through silv_ref_country, so it follows the country list; every member
    -- load below then sees the same run's local group values
    exec Layercake.usp_load_silv_ref_local_group      @run_id = @run_id;

    -- calendar: the config derives its campaign years from the spine
    exec Layercake.usp_load_ref_date_spine            @run_id = @run_id;
    exec Layercake.usp_load_ref_campaign_year_config  @run_id = @run_id;

    -- payments feed the Renewal / Readmission events and the daily paid count
    exec Layercake.usp_load_silv_payment_events       @run_id = @run_id;

    -- curated gap-fill dates for paying contacts with no qualifying enrolment
    -- or election row. BETWEEN THE TWO DELIBERATELY: the capture driver is the
    -- payment events above, and the member base below coalesces the result in.
    -- Insert-only for captures, flag-only for retirement - see the module
    -- header for why, and for how a new capture reaches the daily count.
    exec Layercake.usp_load_ref_enrolment_exception   @run_id = @run_id;

    -- the per-contact base every derivation below reads
    exec Layercake.usp_load_silv_member_base          @run_id = @run_id;

    -- events, then the rule checks over the same base
    exec Layercake.usp_load_silv_membership_events    @run_id = @run_id;
    exec Layercake.usp_load_silv_data_anomaly         @run_id = @run_id;

    -- ranges derive from the events; the profile's affected-date
    -- calculation reads the ranges, so it follows them
    exec Layercake.usp_load_silv_member_state_ranges  @run_id = @run_id;
    exec Layercake.usp_load_silv_member_profile       @run_id = @run_id;

    -- daily counts (detail + main, chunked and marked per chunk)
    if @SkipDailyCount = 0
        exec Layercake.usp_load_silv_daily_count
             @run_id              = @run_id,
             @FullRebuild         = @FullRebuild,
             @RebuildFrom         = @RebuildFrom,
             @DailyCountBatchDays = @DailyCountBatchDays;

    -- segment-level annual counts for the DAX rate measures
    exec Layercake.usp_load_silv_annual_rate_base     @run_id = @run_id;
end
GO
-- Layercake.usp_load_gold (src/sql/Layercake/Procedures/Layercake.usp_load_gold.sql) (changed)
/*====================================================================
    Layercake.usp_load_gold
    Orchestration - calls the per-table modules in order
====================================================================*/

/*====================================================================
    GOLD
    ------------------------------------------------------------------
    Dimensions first (every fact key must resolve, and id 0 is the 'N/A'
    member in each), then the three facts.

    Parameters:
      @run_id          - orchestrator run id (generated if standalone)
      @DetailBatchDays - date-window size for the batched star detail
                         fact load (default 31; minimum 1)
      @SkipDailyFact   - 1 leaves out the star detail fact (ADR-012):
                         usp_run_daily_load runs it itself straight
                         after the daily count. Leave at 0 when calling
                         by hand.
====================================================================*/
create or alter procedure Layercake.usp_load_gold
    @run_id          uniqueidentifier = null,
    @DetailBatchDays int = 31,
    @SkipDailyFact   bit = 0
as
begin
    set nocount on;
    set xact_abort on;

    if @run_id is null set @run_id = newid();

    -- dimensions: straight upserts from the silver refs, ids copied across
    exec Layercake.usp_load_dim_membership_grade  @run_id = @run_id;
    exec Layercake.usp_load_dim_assessment_route  @run_id = @run_id;
    exec Layercake.usp_load_dim_rpq_variant       @run_id = @run_id;
    exec Layercake.usp_load_dim_country           @run_id = @run_id;
    -- MOD-030 (REQ-027): local group keys resolve before any fact load
    exec Layercake.usp_load_dim_local_group       @run_id = @run_id;
    exec Layercake.usp_load_dim_gender            @run_id = @run_id;
    exec Layercake.usp_load_dim_membership_status @run_id = @run_id;
    exec Layercake.usp_load_dim_lapse_reason      @run_id = @run_id;
    exec Layercake.usp_load_dim_campaign_year     @run_id = @run_id;
    exec Layercake.usp_load_dim_date              @run_id = @run_id;

    -- facts
    exec Layercake.usp_load_fact_membership_events @run_id = @run_id;

    if @SkipDailyFact = 0
        exec Layercake.usp_load_fact_daily_member_count_detail
             @run_id          = @run_id,
             @DetailBatchDays = @DetailBatchDays;

    exec Layercake.usp_load_fact_annual_rate_base  @run_id = @run_id;
end
GO
-- ===== changes end =====
